import { Row, Col } from "react-bootstrap";
import { FiDollarSign, FiTrendingUp, FiPackage } from "react-icons/fi";
import { useApp } from "../../context/AppContext";
import StatCard from "../../components/common/StatCard";

export default function Sales() {
  const { currentUser, orders } = useApp();
  // Revenue the dealer has generated by reselling procured stock to customers
  // (in this demo, tracked as delivered purchases the dealer has completed).
  const delivered = orders.filter((o) => o.buyerId === currentUser.id && o.status === "Delivered");
  const totalRevenue = delivered.reduce((sum, o) => sum + o.total, 0);
  const unitsMoved = delivered.reduce((sum, o) => sum + o.items.reduce((s, i) => s + i.qty, 0), 0);

  const byProduct = {};
  delivered.forEach((o) =>
    o.items.forEach((i) => {
      byProduct[i.name] = (byProduct[i.name] || 0) + i.qty * i.price;
    })
  );
  const rows = Object.entries(byProduct).sort((a, b) => b[1] - a[1]);

  return (
    <div>
      <Row className="g-3 mb-4">
        <Col md={4}><StatCard label="Revenue this cycle" value={`₹${totalRevenue.toLocaleString("en-IN")}`} accent="accent-dealer" icon={FiDollarSign} /></Col>
        <Col md={4}><StatCard label="Units moved" value={unitsMoved} icon={FiPackage} /></Col>
        <Col md={4}><StatCard label="Completed deals" value={delivered.length} accent="accent-customer" icon={FiTrendingUp} /></Col>
      </Row>

      <h2 style={{ fontSize: "1.1rem" }} className="mb-3">Revenue by product</h2>
      {rows.length === 0 ? (
        <p style={{ color: "var(--color-muted)" }}>Revenue will appear here once your bulk orders are delivered.</p>
      ) : (
        <div className="gc-card accent-dealer">
          {rows.map(([name, revenue]) => {
            const pct = Math.round((revenue / totalRevenue) * 100);
            return (
              <div key={name} className="mb-3">
                <div className="d-flex justify-content-between" style={{ fontSize: "0.88rem" }}>
                  <span>{name}</span>
                  <strong>₹{revenue.toLocaleString("en-IN")}</strong>
                </div>
                <div style={{ background: "var(--color-line)", borderRadius: 999, height: 8, overflow: "hidden" }}>
                  <div style={{ width: `${pct}%`, background: "var(--role-dealer)", height: "100%" }} />
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}
